using blitz::tools::kind;
using blitz::tools::token;

namespace {
	using namespace blitz::format;

	struct item {
		token tok;
		bool  space_before = false; // There was white space in front of it in the source
		bool  keyword      = false; // A keyword, as opposed to a name
		bool  type_colon   = false; // The : of x:Int32, which gives a type and doesn't separate statements
		std::string lower;
		enum class sign_kind { none, binary, unary, ambiguous };
		sign_kind sign = sign_kind::none;
	};

	struct source_line {
		std::vector<item> items;
		std::string       comment;      // With the semicolon, empty if there is none
		std::string       comment_gap;  // The white space in front of the comment
		std::string       trailing;     // White space after the last item, when there is no comment
		bool              has_comment = false;
	};

	std::vector<source_line> split_lines(std::vector<token> const& tokens, std::string& first_newline)
	{
		std::vector<source_line> lines(1);
		std::string              pending;
		for (auto const& t : tokens) {
			auto& line = lines.back();
			switch (t.type) {
			case kind::space:
				pending += t.text;
				break;
			case kind::newline:
				if (first_newline.empty()) {
					first_newline = t.text;
				}
				line.trailing = pending;
				pending.clear();
				lines.emplace_back();
				break;
			case kind::comment:
				line.comment     = t.text;
				line.comment_gap = pending;
				line.has_comment = true;
				pending.clear();
				break;
			default: {
				item it;
				it.tok          = t;
				it.space_before = !pending.empty();
				pending.clear();
				it.lower = blitz::tools::lower(t.text);
				line.items.push_back(std::move(it));
				break;
			}
			}
		}
		lines.back().trailing = pending;
		return lines;
	}

	bool is_operator_symbol(std::string const& s)
	{
		static const char* ops[] = { "+", "-", "*", "/", "^", "=", "<", ">", "<=", ">=", "<>", "=>", "=<", "><", "==", "~", "|", "&" };
		return std::any_of(std::begin(ops), std::end(ops), [&](const char* o) { return s == o; });
	}

	bool is_open(item const& i)
	{
		return i.tok.is_symbol("(") || i.tok.is_symbol("[");
	}
	bool is_close(item const& i)
	{
		return i.tok.is_symbol(")") || i.tok.is_symbol("]");
	}

	// Mark the keywords and decide for each + - ~ whether it is a sign or an operator.
	void classify_items(std::vector<item>& items)
	{
		for (size_t i = 0; i < items.size(); i++) {
			auto& it = items[i];
			if (it.tok.is(kind::word)) {
				char last = it.tok.text.back();
				bool plain = (last != '%') && (last != '#') && (last != '$');
				bool field = (i > 0) && (items[i - 1].tok.is_symbol("\\") || items[i - 1].tok.is_symbol("."));
				it.keyword = plain && !field && !blitz::tools::keyword_spelling(it.tok.text).empty();
			}
		}
		// A : between a name and a type name that touches both is the type of the name, as the compiler reads it.
		for (size_t i = 1; i + 1 < items.size(); i++) {
			auto& it = items[i];
			if (it.tok.is(kind::separator) && !it.space_before && !items[i + 1].space_before && items[i - 1].tok.is(kind::word) && items[i + 1].tok.is(kind::word) && blitz::tools::is_type_name(items[i + 1].tok.text)) {
				it.type_colon = true;
			}
		}
		for (size_t i = 0; i < items.size(); i++) {
			auto& it = items[i];
			if (!it.tok.is(kind::symbol) || !is_operator_symbol(it.tok.text)) {
				continue;
			}
			bool maybe_sign = (it.tok.text == "-") || (it.tok.text == "+") || (it.tok.text == "~");
			it.sign         = item::sign_kind::binary;
			if (!maybe_sign) {
				continue;
			}
			bool next_space = (i + 1 < items.size()) && items[i + 1].space_before;
			if (i == 0) {
				it.sign = item::sign_kind::unary;
				continue;
			}
			auto const& prev = items[i - 1];
			if (prev.tok.is(kind::separator) || is_open(prev) || prev.tok.is_symbol(",") || (prev.sign == item::sign_kind::binary) || (prev.sign == item::sign_kind::unary)) {
				it.sign = item::sign_kind::unary;
			} else if (prev.keyword && (blitz::tools::keyword_takes_value(prev.lower) || prev.lower == "data")) {
				it.sign = item::sign_kind::unary;
			} else if (prev.tok.is(kind::word) && !prev.keyword && it.space_before && !next_space) {
				it.sign = item::sign_kind::ambiguous; // `Foo -1`: a command with an argument, or a subtraction.
			} else if (prev.sign == item::sign_kind::ambiguous) {
				it.sign = item::sign_kind::binary;
			}
		}
	}

	std::string render_word(item const& it, options const& o)
	{
		if (!it.keyword || (o.keyword_case == keyword_style::preserve)) {
			return it.tok.text;
		}
		switch (o.keyword_case) {
		case keyword_style::lower:
			return it.lower;
		case keyword_style::upper: {
			std::string t = it.tok.text;
			for (auto& c : t) {
				c = char(std::toupper((unsigned char)c));
			}
			return t;
		}
		default:
			return std::string(blitz::tools::keyword_spelling(it.tok.text));
		}
	}

	bool word_like(item const& i)
	{
		return i.tok.is(kind::word) || i.tok.is(kind::number) || i.tok.is(kind::string) || i.tok.is(kind::other);
	}

	std::string spacing_gap(spacing s, bool original)
	{
		switch (s) {
		case spacing::spaced:
			return " ";
		case spacing::compact:
			return "";
		default:
			return original ? " " : "";
		}
	}

	// The white space between two items on a line.
	std::string gap_between(item const& prev, item const& cur, options const& o)
	{
		bool orig = cur.space_before;

		if (cur.tok.is_symbol(",")) {
			return "";
		}
		if (prev.tok.is_symbol(",")) {
			return o.comma_space ? " " : "";
		}
		if (is_close(cur)) {
			return (is_open(prev) || !o.paren_inner_space) ? "" : " ";
		}
		if (is_open(prev)) {
			return o.paren_inner_space ? " " : "";
		}
		if (prev.type_colon || cur.type_colon) {
			return "";
		}
		if (prev.tok.is(kind::separator) || cur.tok.is(kind::separator)) {
			return spacing_gap(o.separator_spacing, orig);
		}
		if (prev.tok.is_symbol("\\") || cur.tok.is_symbol("\\")) {
			return "";
		}
		if (prev.tok.is_symbol(".") || cur.tok.is_symbol(".")) {
			return orig ? " " : "";
		}
		if (cur.sign == item::sign_kind::ambiguous) {
			return orig ? " " : "";
		}
		if (cur.sign == item::sign_kind::binary) {
			return spacing_gap(o.operator_spacing, orig);
		}
		if (prev.sign == item::sign_kind::unary) {
			return "";
		}
		if (prev.sign == item::sign_kind::binary) {
			return spacing_gap(o.operator_spacing, orig);
		}
		if (prev.sign == item::sign_kind::ambiguous) {
			return orig ? " " : "";
		}
		if (cur.sign == item::sign_kind::unary) {
			return " "; // After a keyword or a name that takes a value, as in `Return -1`.
		}
		if (is_open(cur)) {
			if (prev.tok.is(kind::word)) {
				bool call = !prev.keyword || blitz::tools::keyword_is_function(prev.lower);
				if (!call) {
					return " ";
				}
				return (o.paren_space == paren_spacing::never) ? "" : (orig ? " " : "");
			}
			return orig ? " " : "";
		}
		if (word_like(prev) && word_like(cur)) {
			return " ";
		}
		return orig ? " " : "";
	}

	// What a statement does to the nesting.
	enum class block { function, type, loop_for, loop_while, loop_repeat, conditional, select, branch /* the Case of a Select */ };

	struct frame {
		block kind;
		int   weight;
	};

	struct role {
		enum { plain, label, opener, closer, middle, branch } type = plain;
		block kind = block::function;
	};

	std::optional<block> opener_of(std::string const& word)
	{
		if (word == "function") return block::function;
		if (word == "type") return block::type;
		if (word == "for") return block::loop_for;
		if (word == "while") return block::loop_while;
		if (word == "repeat") return block::loop_repeat;
		if (word == "select") return block::select;
		return std::nullopt;
	}

	std::optional<block> closer_of(std::string const& word)
	{
		if (word == "next") return block::loop_for;
		if (word == "wend") return block::loop_while;
		if ((word == "until") || (word == "forever")) return block::loop_repeat;
		if (word == "endif") return block::conditional;
		return std::nullopt;
	}

	// 'statement' is the items of one statement, 'last' tells whether it is the last one on its line.
	role classify(std::vector<item> const& s, bool last)
	{
		role r;
		if (s.empty()) {
			return r;
		}
		if (s[0].tok.is_symbol(".") && (s.size() > 1) && s[1].tok.is(kind::word)) {
			r.type = role::label;
			return r;
		}
		if (!s[0].keyword) {
			return r;
		}
		auto const& w = s[0].lower;
		if (w == "if") {
			// A block If has nothing behind its Then (or condition), and nothing behind it on the line.
			size_t then = s.size();
			int    depth = 0;
			for (size_t i = 1; i < s.size(); i++) {
				if (is_open(s[i])) depth++;
				if (is_close(s[i])) depth--;
				if ((depth == 0) && s[i].keyword && (s[i].lower == "then")) {
					then = i;
					break;
				}
			}
			bool block_form = last && ((then == s.size()) || (then + 1 == s.size()));
			if (block_form) {
				r.type = role::opener;
				r.kind = block::conditional;
			}
			return r;
		}
		if (auto k = opener_of(w)) {
			r.type = role::opener;
			r.kind = *k;
			return r;
		}
		if (auto k = closer_of(w)) {
			r.type = role::closer;
			r.kind = *k;
			return r;
		}
		if ((w == "end") && (s.size() > 1) && s[1].keyword) {
			auto const& n = s[1].lower;
			if (n == "if") { r.type = role::closer; r.kind = block::conditional; }
			if (n == "function") { r.type = role::closer; r.kind = block::function; }
			if (n == "type") { r.type = role::closer; r.kind = block::type; }
			if (n == "select") { r.type = role::closer; r.kind = block::select; }
			return r;
		}
		if ((w == "else") || (w == "elseif")) {
			r.type = role::middle;
			r.kind = block::conditional;
			return r;
		}
		if ((w == "case") || (w == "default")) {
			r.type = role::branch;
			return r;
		}
		return r;
	}

	struct out_line {
		std::string text; // Without the indent
		int         indent = 0;
		bool        blank = true;
		bool        comment_only = false;
		bool        decl_start = false;
		bool        decl_end = false;
		// What align_assignments and align_declares work with.
		enum class align_kind { none, assignment, declaration, data } align = align_kind::none;
		size_t name_at = std::string::npos; // Declarations: where the white space in front of the name starts, which is behind the keyword
		size_t eq_at   = std::string::npos; // Where the white space in front of the single = of the line starts
		std::vector<std::pair<size_t, size_t>> cells; // Data: where the values start and end
	};

	struct nesting {
		std::vector<frame> stack;
		options const&     o;

		int depth() const
		{
			int sum = 0;
			for (auto const& f : stack) {
				sum += f.weight;
			}
			return sum;
		}

		int weight_of(block kind) const
		{
			return (kind == block::select) ? (o.indent_case ? 1 : 0) : 1;
		}

		void push(block kind)
		{
			stack.push_back({ kind, weight_of(kind) });
		}

		bool top_is(block kind) const
		{
			return !stack.empty() && (stack.back().kind == kind);
		}

		// Remove everything down to and including the innermost frame of this kind. Does nothing if there is none.
		bool pop_to(block kind)
		{
			for (size_t i = stack.size(); i-- > 0;) {
				if (stack[i].kind == kind) {
					stack.resize(i);
					return true;
				}
			}
			return false;
		}
	};

	// 'starts' gets the offset in the result at which the white space in front of each item starts.
	std::string render_line(source_line const& line, std::vector<item> const& items, options const& o, std::vector<size_t>* starts = nullptr, std::vector<size_t>* begins = nullptr)
	{
		std::string out;
		for (size_t i = 0; i < items.size(); i++) {
			if (starts) {
				starts->push_back(out.size());
			}
			if (i > 0) {
				out += gap_between(items[i - 1], items[i], o);
			}
			if (begins) {
				begins->push_back(out.size());
			}
			out += items[i].tok.is(kind::word) ? render_word(items[i], o) : items[i].tok.text;
		}
		return out;
	}

	// The index of the first item behind the target of an assignment (a name, with fields and indexes), or 0 if the line doesn't start with one.
	size_t end_of_target(std::vector<item> const& items)
	{
		size_t i = 0;
		if (items.empty() || !items[0].tok.is(kind::word) || items[0].keyword) {
			return 0;
		}
		i++;
		while (i < items.size()) {
			if (items[i].type_colon && (i + 1 < items.size())) {
				i += 2;
			} else if (items[i].tok.is_symbol("\\") && (i + 1 < items.size()) && items[i + 1].tok.is(kind::word)) {
				i += 2;
			} else if (is_open(items[i])) {
				int depth = 0;
				for (; i < items.size(); i++) {
					depth += is_open(items[i]) - is_close(items[i]);
					if (depth == 0) {
						break;
					}
				}
				if (i >= items.size()) {
					return 0;
				}
				i++;
			} else {
				break;
			}
		}
		return i;
	}

	// Works out whether the line is one that align_assignments or align_declares lines up, and where its parts are. Lines with more than one
	// statement are not: `a = 1 : b = 2` has two assignments, and lining up one of them says nothing.
	void describe_alignment(std::vector<item> const& items, std::vector<size_t> const& starts, std::vector<size_t> const& begins, out_line& ol)
	{
		if (items.size() < 2) {
			return;
		}
		for (auto const& it : items) {
			if (it.tok.is(kind::separator) && !it.type_colon) {
				return;
			}
		}

		if (items[0].keyword && (items[0].lower == "data")) {
			// The values, which are what is between the commas.
			ol.align    = out_line::align_kind::data;
			size_t from = 1;
			for (size_t i = 1; i <= items.size(); i++) {
				if ((i == items.size()) || items[i].tok.is_symbol(",")) {
					if (i > from) {
						ol.cells.emplace_back(begins[from], (i == items.size()) ? begins[i - 1] + items[i - 1].tok.text.size() : starts[i]);
					}
					from = i + 1;
				}
			}
			return;
		}

		if (items[0].keyword && ((items[0].lower == "const") || (items[0].lower == "local") || (items[0].lower == "global") || (items[0].lower == "dim"))) {
			ol.align   = out_line::align_kind::declaration;
			ol.name_at = starts[1];
			// One variable per line, or there is no telling which = to line up.
			int depth = 0;
			for (size_t i = 1; i < items.size(); i++) {
				depth += is_open(items[i]) - is_close(items[i]);
				if ((depth == 0) && items[i].tok.is_symbol(",")) {
					return;
				}
			}
			depth = 0;
			for (size_t i = 1; i < items.size(); i++) {
				depth += is_open(items[i]) - is_close(items[i]);
				if ((depth == 0) && items[i].tok.is_symbol("=")) {
					if (i + 1 < items.size()) {
						ol.eq_at = starts[i];
					}
					break;
				}
			}
			return;
		}

		size_t target = end_of_target(items);
		if ((target > 0) && (target + 1 < items.size()) && items[target].tok.is_symbol("=")) {
			ol.align = out_line::align_kind::assignment;
			ol.eq_at = starts[target];
		}
	}

	// Lines that follow each other with the same indent and the same kind are lined up: the = of assignments and declarations, and the names
	// of declarations (Const, Local, Global and Dim have different lengths).
	void align_lines(std::vector<out_line>& lines, options const& o)
	{
		for (size_t first = 0; first < lines.size();) {
			auto what = lines[first].align;
			size_t last = first + 1;
			while ((last < lines.size()) && (lines[last].align == what) && (lines[last].indent == lines[first].indent)) {
				last++;
			}
			bool wanted = (what == out_line::align_kind::assignment) ? o.align_assignments : ((what == out_line::align_kind::declaration) ? o.align_declares : ((what == out_line::align_kind::data) && o.align_data != data_alignment::off));
			if (wanted && (what == out_line::align_kind::data) && (last - first > 1)) {
				// Each column is as wide as its widest value, and the next value starts behind it.
				std::vector<size_t> widths;
				for (size_t i = first; i < last; i++) {
					for (size_t c = 0; c < lines[i].cells.size(); c++) {
						if (c >= widths.size()) {
							widths.push_back(0);
						}
						widths[c] = std::max(widths[c], lines[i].cells[c].second - lines[i].cells[c].first);
					}
				}
				bool right = o.align_data == data_alignment::right;
				for (size_t i = first; i < last; i++) {
					// Right aligned values start behind the padding of their own width, so that the commas are in a column.
					for (size_t c = lines[i].cells.size(); c-- > (right ? 0 : 1);) {
						size_t pad = right ? widths[c] - (lines[i].cells[c].second - lines[i].cells[c].first) : widths[c - 1] - (lines[i].cells[c - 1].second - lines[i].cells[c - 1].first);
						lines[i].text.insert(right ? lines[i].cells[c].first : lines[i].cells[c].first, std::string(pad, ' '));
					}
				}
			} else if (wanted && (last - first > 1)) {
				if (what == out_line::align_kind::declaration) {
					size_t width = 0;
					for (size_t i = first; i < last; i++) {
						width = std::max(width, lines[i].name_at);
					}
					for (size_t i = first; i < last; i++) {
						size_t pad = width - lines[i].name_at;
						lines[i].text.insert(lines[i].name_at, std::string(pad, ' '));
						if (lines[i].eq_at != std::string::npos) {
							lines[i].eq_at += pad;
						}
					}
				}
				size_t width = 0;
				for (size_t i = first; i < last; i++) {
					if (lines[i].eq_at != std::string::npos) {
						width = std::max(width, lines[i].eq_at);
					}
				}
				for (size_t i = first; i < last; i++) {
					if (lines[i].eq_at != std::string::npos) {
						lines[i].text.insert(lines[i].eq_at, std::string(width - lines[i].eq_at, ' '));
					}
				}
			}
			first = last;
		}
	}

	// Breaks a line that is longer than wrap_after at a : between statements, which is the only place where the language allows it
	// (there is no way to continue a statement on the next line). Statements after the start of an If stay where they are: in
	// `If a Then b : c` the c is part of the If, and on a line of its own it would not be. Returns whether the line was split.
	bool wrap_line(std::vector<source_line>& lines, size_t n, int depth, options const& o)
	{
		auto& line = lines[n];
		classify_items(line.items);
		std::vector<size_t> starts;
		std::string         text = render_line(line, line.items, o, &starts);
		size_t              indent_cols = size_t(depth) * size_t(o.indent_width);
		size_t              total       = indent_cols + text.size() + (line.has_comment ? (o.comment_gap > 0 ? size_t(o.comment_gap) : line.comment_gap.size()) + line.comment.size() : 0);
		if (total <= size_t(o.wrap_after)) {
			return false;
		}

		auto const& items       = line.items;
		size_t      limit       = items.size(); // Separators behind the start of an If are not safe
		bool        statement_start = true;
		for (size_t i = 0; i < items.size(); i++) {
			if (statement_start && items[i].keyword && ((items[i].lower == "if") || (items[i].lower == "else") || (items[i].lower == "elseif"))) {
				limit = i;
				break;
			}
			statement_start = items[i].tok.is(kind::separator) && !items[i].type_colon;
		}
		std::vector<size_t> candidates;
		for (size_t i = 1; i + 1 < items.size() && i < limit; i++) {
			bool separator = items[i].tok.is(kind::separator) && !items[i].type_colon;
			bool empty_side = (items[i - 1].tok.is(kind::separator) && !items[i - 1].type_colon) || (items[i + 1].tok.is(kind::separator) && !items[i + 1].type_colon);
			if (separator && !empty_side) {
				candidates.push_back(i);
			}
		}
		if (candidates.empty()) {
			return false;
		}
		size_t at = candidates.front();
		for (auto c : candidates) {
			if (indent_cols + starts[c] <= size_t(o.wrap_after)) {
				at = c;
			}
		}

		source_line first, second;
		first.items.assign(items.begin(), items.begin() + std::ptrdiff_t(at));
		second.items.assign(items.begin() + std::ptrdiff_t(at) + 1, items.end());
		second.items.front().space_before = false;
		second.comment     = line.comment;
		second.comment_gap = line.comment_gap;
		second.has_comment = line.has_comment;
		second.trailing    = line.trailing;
		lines[n]           = std::move(first);
		lines.insert(lines.begin() + std::ptrdiff_t(n) + 1, std::move(second));
		return true;
	}

	std::string render_comment(std::string text, options const& o)
	{
		if (o.trim_trailing_space) {
			while (!text.empty() && ((text.back() == ' ') || (text.back() == '\t'))) {
				text.pop_back();
			}
		}
		if (o.comment_space && (text.size() > 1) && (std::isalnum((unsigned char)text[1]) || (text[1] == '_'))) {
			text.insert(1, " ");
		}
		return text;
	}
} // namespace

std::string blitz::format::format_source(std::string const& source_in, options const& o)
{
	std::string source = source_in;
	bool        bom    = source.compare(0, 3, "\xEF\xBB\xBF") == 0;
	if (bom) {
		source.erase(0, 3);
	}

	auto        tokens = blitz::tools::tokenize(source);
	std::string first_newline;
	auto        lines = split_lines(tokens, first_newline);

	nesting           nest{ {}, o };
	std::vector<out_line> out;
	out.reserve(lines.size());

	for (size_t n = 0; n < lines.size(); n++) {
		if (o.wrap_after > 0) {
			wrap_line(lines, n, nest.depth(), o);
		}
		auto&    line = lines[n];
		out_line ol;
		classify_items(line.items);

		// Split into statements at the separators.
		std::vector<std::vector<item>> statements(1);
		for (auto const& it : line.items) {
			if (it.tok.is(kind::separator) && !it.type_colon) {
				statements.emplace_back();
			} else {
				statements.back().push_back(it);
			}
		}

		std::optional<int> indent;
		bool               is_label = false;
		for (size_t s = 0; s < statements.size(); s++) {
			auto& st = statements[s];
			if (st.empty()) {
				continue;
			}
			role r     = classify(st, s + 1 == statements.size());
			bool first = !indent.has_value();
			switch (r.type) {
			case role::label:
				if (first) {
					is_label = true;
					indent   = o.indent_labels ? nest.depth() : 0;
				}
				break;
			case role::opener:
				if (first) indent = nest.depth();
				if (first && nest.stack.empty() && ((r.kind == block::function) || (r.kind == block::type))) ol.decl_start = true;
				nest.push(r.kind);
				break;
			case role::closer: {
				bool was_top_level = !nest.stack.empty() && ((nest.stack.front().kind == block::function) || (nest.stack.front().kind == block::type));
				nest.pop_to(r.kind);
				if (first) indent = nest.depth();
				if (was_top_level && nest.stack.empty()) ol.decl_end = true;
				break;
			}
			case role::middle:
				if (nest.top_is(block::conditional)) {
					nest.stack.pop_back();
					if (first) indent = nest.depth();
					nest.push(block::conditional);
				} else if (first) {
					indent = nest.depth();
				}
				break;
			case role::branch:
				if (nest.top_is(block::branch)) {
					nest.stack.pop_back();
				}
				if (nest.top_is(block::select)) {
					if (first) indent = nest.depth();
					nest.stack.push_back({ block::branch, 1 });
				} else if (first) {
					indent = nest.depth();
				}
				break;
			default:
				if (first) indent = nest.depth();
				break;
			}
		}

		ol.indent = indent.value_or(nest.depth());
		(void)is_label;
		std::vector<size_t> starts, begins;
		std::string         text     = render_line(line, line.items, o, &starts, &begins);
		bool                has_code = !line.items.empty();
		describe_alignment(line.items, starts, begins, ol);
		if (line.has_comment) {
			std::string gap;
			if (has_code) {
				gap = (o.comment_gap > 0) ? std::string(size_t(o.comment_gap), ' ') : line.comment_gap;
			}
			text += gap + render_comment(line.comment, o);
		} else if (!o.trim_trailing_space) {
			text += line.trailing;
		}
		ol.text         = text;
		ol.blank        = !has_code && !line.has_comment;
		ol.comment_only = !has_code && line.has_comment;
		if (ol.blank && !o.trim_trailing_space) {
			ol.text = line.trailing;
		}
		out.push_back(std::move(ol));
	}

	// The last "line" is what comes after the final line break: nothing, or an unfinished line.
	if (!out.empty() && out.back().blank && out.back().text.empty()) {
		out.pop_back();
	}

	// Blank lines.
	std::vector<int> need(out.size() + 1, 0);
	if (o.blank_lines_around_declarations > 0) {
		for (size_t i = 0; i < out.size(); i++) {
			if (out[i].decl_start) {
				size_t s = i;
				while ((s > 0) && out[s - 1].comment_only) {
					s--;
				}
				need[s] = std::max(need[s], o.blank_lines_around_declarations);
			}
			if (out[i].decl_end) {
				size_t j = i + 1;
				while ((j < out.size()) && out[j].blank) {
					j++;
				}
				if (j < out.size()) {
					need[j] = std::max(need[j], o.blank_lines_around_declarations);
				}
			}
		}
	}

	std::vector<out_line> result;
	int                   blanks = 0;
	for (size_t i = 0; i < out.size(); i++) {
		auto& l = out[i];
		if (l.blank) {
			if (result.empty() || ((o.max_blank_lines >= 0) && (blanks >= o.max_blank_lines))) {
				continue;
			}
			blanks++;
			result.push_back(l);
			continue;
		}
		int want = need[i];
		if (o.max_blank_lines >= 0) {
			want = std::min(want, o.max_blank_lines);
		}
		for (; !result.empty() && (blanks < want); blanks++) {
			out_line b;
			result.push_back(b);
		}
		blanks = 0;
		result.push_back(l);
	}
	while (!result.empty() && result.back().blank) {
		result.pop_back();
	}

	if (o.align_assignments || o.align_declares || (o.align_data != data_alignment::off)) {
		align_lines(result, o);
	}

	std::string newline;
	switch (o.line_ending) {
	case ending_style::lf:
		newline = "\n";
		break;
	case ending_style::crlf:
		newline = "\r\n";
		break;
	case ending_style::cr:
		newline = "\r";
		break;
	default:
		newline = first_newline.empty() ? "\n" : first_newline;
		break;
	}

	std::string indent_unit = o.indent_with_tabs ? "\t" : std::string(size_t(o.indent_width), ' ');
	std::string text;
	for (size_t i = 0; i < result.size(); i++) {
		auto const& l = result[i];
		if (!l.blank || !l.text.empty()) {
			for (int k = 0; k < l.indent; k++) {
				text += indent_unit;
			}
			text += l.text;
		}
		if ((i + 1 < result.size()) || o.final_newline) {
			text += newline;
		}
	}
	if (bom) {
		text.insert(0, "\xEF\xBB\xBF");
	}

	if (!same_program(source_in, text)) {
		throw std::runtime_error("The formatted program is not the same program as the input. This is a bug in blitz-format, nothing was changed.");
	}
	return text;
}

bool blitz::format::same_program(std::string const& a, std::string const& b)
{
	auto reduce = [](std::string const& text) {
		std::string source = text;
		if (source.compare(0, 3, "\xEF\xBB\xBF") == 0) {
			source.erase(0, 3);
		}
		std::vector<token> out;
		for (auto& t : blitz::tools::tokenize(source)) {
			if (t.type == kind::space) {
				continue;
			}
			if (t.type == kind::separator) {
				// A : between statements is the same as a line break (wrap_after turns one into the other).
				t.type = kind::newline;
			}
			if (t.type == kind::newline) {
				if (out.empty() || out.back().type == kind::newline) {
					continue;
				}
				t.text = "\n";
			}
			if (t.type == kind::comment) {
				size_t begin = 1, end = t.text.size();
				while ((begin < end) && ((t.text[begin] == ' ') || (t.text[begin] == '\t'))) {
					begin++;
				}
				while ((end > begin) && ((t.text[end - 1] == ' ') || (t.text[end - 1] == '\t'))) {
					end--;
				}
				t.text = t.text.substr(begin, end - begin);
			}
			out.push_back(std::move(t));
		}
		while (!out.empty() && (out.back().type == kind::newline)) {
			out.pop_back();
		}
		return out;
	};

	auto ta = reduce(a), tb = reduce(b);
	if (ta.size() != tb.size()) {
		return false;
	}
	for (size_t i = 0; i < ta.size(); i++) {
		if (ta[i].type != tb[i].type) {
			return false;
		}
		if (ta[i].text == tb[i].text) {
			continue;
		}
		// Only the case of a keyword may differ.
		if (!(ta[i].type == kind::word) || (blitz::tools::lower(ta[i].text) != blitz::tools::lower(tb[i].text)) || blitz::tools::keyword_spelling(ta[i].text).empty()) {
			return false;
		}
	}
	return true;
}
